contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try withdrawing up to some amount; ensure observable invariants about balances and Ether flow.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // No precondition on c's state; ensure this test contract can receive ETH from c if transfer happens
        // (the test harness supplies Ether to this contract as needed).

        // Read observable before-values
        uint256 beforeContractBal = address(c).balance;
        // balances mapping is not public in C (it's private), so we cannot read it directly. However withdraw requires
        // amount <= balances[msg.sender], so a successful withdraw will reduce address(c).balance by amount and
        // increase address(this).balance by amount. We can observe those.

        // Attempt withdraw and record whether it reverted
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractBal = address(c).balance;
        uint256 afterThisBal = address(this).balance;

        // General rule:
        // - withdraw never increases the contract's balance: afterContractBal <= beforeContractBal
        // - if withdraw succeeded then contract balance decreased by exactly amount and this contract's balance increased by exactly amount
        // - if withdraw reverted then balances unchanged (contract balance unchanged and this contract's balance unchanged)
        assert((afterContractBal <= beforeContractBal) &&
               (( !reverted && afterContractBal + amount == beforeContractBal && afterThisBal >= amount) || (reverted && afterContractBal == beforeContractBal)));
    }

    // allow receiving ETH from c.transfer
    receive() external payable {}
}

